import React from "react";
import { StyleSheet, Text, View, TouchableOpacity } from "react-native";

export function Nota({ item, onPress }) {
  if (!item) {
    return null;
  }

  const categorias = { 
    Pessoal: "#FF924F", 
    Trabalho: "#2F71EB", 
    Estudos: "#9C27B0",
    Lembretes: "#009688",
    Outros: "#00911F" 
  };

  // Extrai dados da nota
  let textoNota = "";
  let categoria = "Pessoal";

  if (Array.isArray(item) && item.length >= 2) {
    textoNota = item[1];
    categoria = item[2] || "Pessoal";
  } else if (item && typeof item === 'object' && item.texto) {
    textoNota = item.texto;
    categoria = item.categoria || "Pessoal";
  } else {
    textoNota = String(item);
  }

  const cor = categorias[categoria] || categorias.Pessoal;
  const style = styleFunction(cor);

  return (
    <TouchableOpacity onPress={onPress}>
      <View style={style.cartao}>
        <View style={style.cabecalho}>
          <Text style={style.categoria}>{categoria}</Text>
        </View>
        <Text style={style.texto} numberOfLines={5}>
          {textoNota}
        </Text>
      </View>
    </TouchableOpacity>
  );
}

const styleFunction = (cor) =>
  StyleSheet.create({
    cartao: {
      borderRadius: 8,
      backgroundColor: "#ffffff",
      paddingVertical: 12,
      paddingHorizontal: 16,
      marginHorizontal: 16,
      marginBottom: 12,
      borderTopWidth: 5,
      borderColor: cor,
      shadowColor: "#000",
      shadowOffset: {
        width: 0,
        height: 2,
      },
      shadowOpacity: 0.23,
      shadowRadius: 2.62,
      elevation: 4,
    },
    cabecalho: {
      flexDirection: "row",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: 8,
    },
    categoria: {
      backgroundColor: cor,
      color: "#FFFFFF",
      paddingHorizontal: 8,
      paddingVertical: 4,
      borderRadius: 12,
      fontSize: 12,
      fontWeight: "bold",
      overflow: "hidden",
    },
    texto: {
      lineHeight: 24,
      fontSize: 16,
      color: "#333333",
    },
  });
